import { createServer } from 'node:http';
const challenge = `<!doctype html><html><head><meta charset="utf-8"><title>Verify you are human</title></head><body style="font:24px sans-serif;padding:48px"><h1>Verify you are human</h1><p>Controlled browser integration fixture. Public creator posts require manual verification.</p><button style="font-size:24px;padding:24px" onclick="document.cookie='human_verified=1;path=/;max-age=86400';location.reload()">我已完成验证 / I am human</button></body></html>`;
const content = `<!doctype html><html><head><meta charset="utf-8"><title>Test Creator — Tech post</title></head><body style="font:24px sans-serif;padding:48px"><h1>Test Creator 的公开帖子</h1><p>Controlled fixture — not a real social profile.</p><article style="padding:32px;background:#ddf0e5;border:2px solid #165f50"><h2>科技教学：芯片、电路板</h2><p>发布于 2026-10-09。讲解处理器与电脑硬件。</p><div style="height:180px;background:#194f36;color:white;display:grid;place-items:center">CHIP / CIRCUIT BOARD · 芯片与电路板</div></article><a href="/post">查看原始帖子</a></body></html>`;
createServer((request, response) => { response.setHeader('Content-Type','text/html; charset=utf-8'); const key = 'human_' + (new URL(request.url, 'http://fixture').searchParams.get('case') ?? 'verified').replace(/[^a-zA-Z0-9_-]/g, ''); response.end(request.url !== '/skip' && (request.headers.cookie ?? '').includes(key + '=1') ? content : challenge.replace('human_verified=1', key + '=1')); }).listen(8085, '0.0.0.0');
